"""Anonymous mechanism reporting; generated by actual diagnostic aggregators."""
from __future__ import annotations

import copy
import importlib.util
import json
from pathlib import Path

import numpy as np
import pytest

from scripts.diagnose_phase28 import aggregate_patient_diagnostics, history_summary


ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location('phase28_mechanism_report', ROOT/'scripts/report_phase28_mechanism.py')
report = importlib.util.module_from_spec(spec); spec.loader.exec_module(report)
SOURCE, OWN_SHA = 'a'*64, 'b'*64
DIAG_SHA = report.sha(ROOT/'scripts/diagnose_phase28.py')


def history(arm, scale):
    enabled = arm != 'C00'
    rows = [{'epoch': epoch, 'cox_loss': 5.-epoch/100, 'regularizer': .3, 'objective': 5.3-epoch/100,
        'risk_RMS': .5, 'main_residual_RMS': .1, 'interaction_RMS': .001*scale if enabled else 0.,
        'clipped_from_gradient_L2': 2., 'maximum_absolute_component_replay_error': 0.,
        'data_gradient_L2_by_top_level_module': {'up': scale*.01 if enabled else 0., 'ug': scale*.02 if enabled else 0.},
        'total_gradient_L2_by_top_level_module': {'up': scale*.03, 'ug': scale*.01}} for epoch in range(1, 81)]
    base = np.array([.1, .2, -.2, -.3])
    interaction = np.array([.01, .02, -.01, -.02])*scale if enabled else np.zeros(4)
    return history_summary({'history': rows,
        'fit_components': {'risk': base+interaction, 'base': base, 'interaction': interaction,
                           'path_main': np.zeros(4), 'gene_main': base},
        'training_audit': {'final_fit_Efron_NLL': 4.19}})


def mechanism(arm, scale):
    path_on, gene_on = arm in ('C10', 'C11', 'DIRECT'), arm in ('C01', 'C11', 'DIRECT')
    rows = []
    for example in range(3):
        layers = []
        for layer in range(2):
            def stats(enabled, gene=False):
                tv = .9 if arm == 'DIRECT' else .1*(example+1)*scale
                return {'TV_mean_all_valid_queries': tv,
                    'TV_mean_queries_ge2_candidates': None if not gene and example == 0 else tv*1.5,
                    'eligible_query_fraction_ge2_candidates': 0. if not gene and example == 0 else .8,
                    'evidence_read_difference_RMS': .03*scale,
                    'anchored_token_change_RMS': .01*scale if enabled else 0.,
                    'anchored_token_change_maximum_absolute': .03*scale if enabled else 0.,
                    'gate_mean': .5, 'gate_fraction_lt_point01': 0., 'gate_fraction_gt_point99': 0.}
            layers.append({'round': layer+1, 'path_equal_WSI': stats(path_on), 'gene': stats(gene_on, True),
                'routing_equal_WSI': {'path_target_null_probability_mean': .2, 'gene_target_null_probability_mean': .3},
                'path_risk_correction': .001 if path_on else 0., 'gene_risk_correction': .002 if gene_on else 0.})
        gradients = {'original_RNA_to_path_risk_L2': .01*scale if path_on else 0.,
            'original_Ep_to_gene_risk_L2': .02*scale if gene_on else 0.,
            'isolated_gene_context_to_path_risk_L2': .03*scale if path_on else 0.,
            'isolated_path_context_to_gene_risk_L2': .04*scale if gene_on else 0.,
            'minimum_nonzero_gradient_threshold_enforced': False}
        rows.append({'layers': layers, 'gradients': gradients, 'risk': {'risk': .3, 'base': .2,
            'interaction': .001 if path_on or gene_on else 0.}})
    result = aggregate_patient_diagnostics(rows)
    from scripts.diagnose_phase28 import moments
    result['frozen_control_sensitivities'] = {name+'_minus_MATCHED': moments(np.array([.001, -.002, .003])*scale)
        for name in report.CONTROLS}
    result.update(selection='fit_only_original_selected_Patch_count_min_lower_median_max;canonical_index_tiebreak',
        read_or_control_aggregation='first_equal_WSI_within_patient_then_equal_three_geometry_examples',
        forbidden_API_call_counts={}, valid_endpoint_reads=0, valid_patient_forward_calls=0,
        fit_endpoint_getter_calls=0, new_optimizer_steps=0, model_weights_unchanged=True,
        external_offset_unchanged=True, fit_geometry_examples_are_not_independent_validation=True,
        gradient_nonzero_is_not_DSS_increment_evidence=True,
        frozen_intervention_is_not_retrained_necessity_evidence=True)
    return result


def fixture_reports(directory):
    diagnostics = directory/'diagnostics'; diagnostics.mkdir()
    reports, bindings = {}, []
    for seed in report.SEEDS:
        for fold in report.FOLDS:
            for arm in report.ARMS:
                digest = report.hashlib.sha256(f'SYNTHETIC-{seed}-{fold}-{arm}'.encode()).hexdigest()
                bindings.append({'seed': seed, 'fold': fold, 'arm': arm, 'checkpoint_sha256': digest})
                scale = .5+seed/100+fold/10
                shared_history = history(arm, scale)
                for mode in ('history', 'mechanism'):
                    value = {'version': 'phase28_postfit_diagnostics_v1', 'status': 'PASS_POSTFIT_'+mode.upper()+'_DIAGNOSTICS',
                        'mode': mode, 'source': SOURCE, 'script_path': 'scripts/diagnose_phase28.py', 'script_sha256': DIAG_SHA,
                        'seed': seed, 'fold': fold, 'arm': arm, 'checkpoint_sha256': digest,
                        'history': copy.deepcopy(shared_history), 'valid_endpoint_reads': 0, 'new_optimizer_steps': 0,
                        'hyperparameters_or_checkpoint_changed': False}
                    if mode == 'mechanism': value['mechanism'] = mechanism(arm, scale)
                    reports[seed, fold, arm, mode] = value
                    write(diagnostics/f'seed{seed}_fold{fold}_{arm}_{mode}.json', value)
    results = {'status': 'COMPLETE_BIDIRECTIONAL_REREAD_INNER_PROTOTYPE', 'source': SOURCE, 'stage': 'prototype',
        'valid_endpoint_callback_calls': 1, 'artifact_audit': {'status': 'PASS_COMPLETE_CHECKPOINT_CONTRACT',
            'neural_models': 30, 'optimizer_steps': 2400, 'model_bindings': bindings},
        'independent_replay': {'status': 'PASS', 'source': SOURCE, 'neural_models': 30, 'risk_vectors_replayed': 300}}
    write(directory/'INNER_RESULTS.json', results)
    return results, reports


def write(path, value):
    path.write_text(json.dumps(value, indent=2, sort_keys=True, allow_nan=False), encoding='utf-8')


def generate(path):
    return report.generate(path, SOURCE, diagnostic_script_sha256=DIAG_SHA, summarizer_script_sha256=OWN_SHA)


def test_real_aggregate_schema_preserves_active_direction_and_direct_nonuse(tmp_path):
    fixture_reports(tmp_path)
    sentinel = b'keep existing five-report contract byte-for-byte'
    (tmp_path/'FORMAL_DELIVERY.json').write_bytes(sentinel)
    payload = generate(tmp_path)
    assert payload['history_reports'] == payload['mechanism_reports'] == payload['models'] == 30
    assert len(payload['input_report_sha256']) == 61
    assert (tmp_path/'FORMAL_DELIVERY.json').read_bytes() == sentinel
    arms = {row['arm']: row for row in payload['arms']}
    assert arms['C00']['rounds'][0]['path']['operative_raw_read_TV_all_valid'] is None
    assert arms['C00']['rounds'][0]['gene']['operative_raw_read_TV_all_valid'] is None
    assert arms['C10']['rounds'][0]['path']['operative_raw_read_TV_all_valid'] is not None
    assert arms['C10']['rounds'][0]['gene']['operative_raw_read_TV_all_valid'] is None
    assert arms['C01']['rounds'][0]['path']['operative_raw_read_TV_all_valid'] is None
    assert arms['C01']['rounds'][0]['gene']['operative_raw_read_TV_all_valid'] is not None
    direct = arms['DIRECT']['rounds'][0]
    assert direct['path']['operative_raw_read_TV_all_valid'] is None
    assert direct['gene']['operative_raw_read_TV_all_valid'] is None
    assert direct['path']['computed_read_diagnostics_not_necessarily_used']['TV_mean_all_valid_queries']['mean_equal_cells'] == pytest.approx(.9)
    assert direct['path']['delta_input_type'] == 'projected_cross_modal_message'
    assert direct['path']['computed_delta_input_RMS']['mean_equal_cells'] > 0
    assert arms['DIRECT']['read_risk_associations']['path'] is None
    assert payload['norm_difference_used_as_regularizer_gradient_norm'] is False
    assert generate(tmp_path) == payload


def test_partial_ge2_candidate_example_count_is_not_faked_as_three(tmp_path):
    fixture_reports(tmp_path)
    result = generate(tmp_path)
    arm = next(row for row in result['arms'] if row['arm'] == 'C11')
    read = arm['rounds'][0]['path']
    assert read['operative_raw_read_TV_at_least_two_candidates']['available_cells'] == 6
    assert read['computed_read_diagnostics_not_necessarily_used']['at_least_two_candidate_example_count_per_cell']['mean_equal_cells'] == 2


def test_equal_cell_aggregation_and_gradient_norms_are_not_subtracted(tmp_path):
    _, reports = fixture_reports(tmp_path)
    result = report.summarize_arm('C11', reports)
    actual = [reports[seed, fold, 'C11', 'mechanism']['history']['saved_fit_risk_components']['interaction']['RMS']
              for seed in report.SEEDS for fold in report.FOLDS]
    assert result['all_fit_interaction_RMS']['mean_equal_cells'] == pytest.approx(sum(actual)/6)
    gradient = result['last10_parameter_gradient_norms']['ug']
    assert gradient['total_including_L2_gradient_L2']['mean_equal_cells'] < gradient['data_gradient_L2']['mean_equal_cells']
    assert 'regularizer_gradient_L2' not in gradient
    assert gradient['norm_difference_is_not_regularizer_gradient_norm'] is True


@pytest.mark.parametrize('tamper', ['source', 'script', 'checkpoint', 'missing', 'history_drift', 'events',
    'optimizer', 'valid_forward', 'binding', 'two_rounds', 'gradient_missing', 'selection'])
def test_incomplete_or_unbound_diagnostics_refuse_summary(tmp_path, tamper):
    results, reports = fixture_reports(tmp_path)
    key = 31, 1, 'C11', 'mechanism'
    value = reports[key]
    path = tmp_path/'diagnostics/seed31_fold1_C11_mechanism.json'
    if tamper == 'source': value['source'] = 'f'*64
    if tamper == 'script': value['script_sha256'] = 'f'*64
    if tamper == 'checkpoint': value['checkpoint_sha256'] = 'f'*64
    if tamper == 'missing': path.unlink()
    if tamper == 'history_drift': value['history']['gradient_clip_fraction'] += .1
    if tamper == 'events': value['valid_endpoint_reads'] = 1
    if tamper == 'optimizer': value['mechanism']['new_optimizer_steps'] = 1
    if tamper == 'valid_forward': value['mechanism']['valid_patient_forward_calls'] = 1
    if tamper == 'binding':
        results['artifact_audit']['model_bindings'][0]['checkpoint_sha256'] = 'f'*64
        write(tmp_path/'INNER_RESULTS.json', results)
    if tamper == 'two_rounds': value['mechanism']['layers'].pop()
    if tamper == 'gradient_missing': del value['mechanism']['gradient_sensitivities'][report.GRADIENTS[0]]
    if tamper == 'selection': value['mechanism']['selection'] = 'select_best_predicted_patients'
    if tamper != 'missing': write(path, value)
    with pytest.raises((ValueError, FileNotFoundError)):
        generate(tmp_path)
    assert not (tmp_path/'MECHANISM_RESULTS.md').exists()
    assert not (tmp_path/'MECHANISM_SUMMARY.json').exists()


def test_read_risk_association_has_no_invented_constant_correlation():
    result = report.association([0., 0., 0., 0., 0., 0.], [1., 2., 3., 4., 5., 6.])
    assert result['Pearson_r'] is None
    assert result['reason'] == 'constant_cell_statistic'
    assert report.association([None]*6, [1.]*6)['cells'] == 0


def test_missing_real_diagnostics_and_conflicting_output_fail_closed(tmp_path):
    with pytest.raises(FileNotFoundError): generate(tmp_path)
    fixture_reports(tmp_path)
    (tmp_path/'MECHANISM_RESULTS.md').write_text('different old report', encoding='utf-8')
    with pytest.raises(ValueError, match='refusing overwrite'): generate(tmp_path)
